using System;using System.Collections.Generic;
namespace UnityEngine.Events {public delegate void UnityAction();}
public enum MetaType {None}
public delegate object TooltipDataGetter();
public class KeyValueField {public UnityEngine.Events.UnityAction on_click_value;public string value;}
public class StatsWindow {public Dictionary<string,KeyValueField> rows=new Dictionary<string,KeyValueField>();protected KeyValueField showStatRow(string label,object value,string icon,MetaType meta,long id,bool flag,string str1,string str2,TooltipDataGetter getter,bool flag2){KeyValueField row;if(!rows.TryGetValue(label,out row)){row=new KeyValueField();rows[label]=row;}row.value=value.ToString();return row;}public virtual void updateStats(){}}
public class CityWindow:StatsWindow {public City selected;public City getMetaObject(){return selected;}public override void updateStats(){NativeEconomyUI.ShowCity(this);}}
public class KingdomWindow:StatsWindow {public Kingdom selected;public Kingdom getMetaObject(){return selected;}}
public class FamilyWindow:StatsWindow {public Family selected;public Family getMetaObject(){return selected;}}
public class UnitWindow:StatsWindow {public Actor selected;protected Actor get_actor(){return selected;}}
namespace UnityEngine {public static class Debug {public static List<string> warnings=new List<string>();public static void LogWarning(object s){warnings.Add(s.ToString());}}}
public class BaseSystemData {public long id;readonly Dictionary<string,object> values=new Dictionary<string,object>();public void get(string k,out string v,string d){object x;v=values.TryGetValue(k,out x)?(string)x:d;}public void get(string k,out int v,int d){object x;v=values.TryGetValue(k,out x)?(int)x:d;}public void get(string k,out long v,long d){object x;v=values.TryGetValue(k,out x)?(long)x:d;}public void set(string k,string v){values[k]=v;}public void set(string k,int v){values[k]=v;}public void set(string k,long v){values[k]=v;}}
public class SaveCustomData:BaseSystemData {}public class CityData:BaseSystemData{public long kingdomID;}public class ActorData:BaseSystemData {public int money;}public class FamilyData:BaseSystemData {}public class KingdomData:BaseSystemData{}public class WarData:BaseSystemData{}
public class MapStats {public int year;public SaveCustomData custom_data=new SaveCustomData();}public class MapBox {internal MapStats map_stats=new MapStats();public CityManager cities=new CityManager();}public static class World {public static MapBox world=new MapBox();}public class CityManager {public List<City> list=new List<City>();}
public class BaseStats {public float this[string key]{get{return 10;}}}public class BaseSimObject{internal BaseStats stats=new BaseStats();}
public class Actor:BaseSimObject {internal ActorData data=new ActorData();public Family family;public City city;public bool alive=true,baby;public int experience;public List<Actor> children=new List<Actor>();public ActorData getData(){return data;}public bool isAlive(){return alive;}internal void addExperience(int x){experience+=x;}public City getCity(){return city;}public bool isBaby(){return baby;}public bool isKing(){return false;}public bool isCityLeader(){return false;}public bool changeHappiness(string k,int a){return true;}public IEnumerable<Actor> getChildren(bool unused){return children;}}
public class Family {public FamilyData data=new FamilyData();public List<Actor> units=new List<Actor>();}
public class Culture {public HashSet<string> traits=new HashSet<string>();public bool addTrait(string s,bool b){return traits.Add(s);}}
public class Kingdom {public KingdomData data=new KingdomData();public List<War> wars=new List<War>();public List<City> cities=new List<City>();public City capital;public Actor king;public Culture culture=new Culture();public IEnumerable<War> getWars(bool b){return wars;}public void setCapital(City c){capital=c;}}
public class CityStatus{public int population,population_adults,warrior_slots;}
public class City {public CityData data=new CityData();internal Kingdom kingdom;internal float timer_build=10;internal float _timer_warrior=10;public float timer_action=10;public CityStatus status=new CityStatus();public Actor leader;public List<Actor> units=new List<Actor>();public int buildings=3,soldiers;public Dictionary<string,int> resources=new Dictionary<string,int>();public bool alive=true;public bool isAlive(){return alive;}public bool isCapitalCity(){return kingdom!=null&&kingdom.capital==this;}public int getPopulationPeople(){return status.population;}public int getResourcesAmount(string r){int n;resources.TryGetValue(r,out n);return GodWorldRuntime.ResourceTotal(this,r,n);}public void takeResource(string r,int n){n=GodWorldRuntime.DrainReserve(this,r,n);int old;resources.TryGetValue(r,out old);resources[r]=Math.Max(0,old-n);}public int addResourcesToRandomStockpile(string r,int n){int old;resources.TryGetValue(r,out old);resources[r]=GodWorldRuntime.SaturatingResourceSum(old,n);return resources[r];}public int countWarriors(){return soldiers;}public int countBuildings(){return buildings;}public bool hasLeader(){return leader!=null;}public void removeLeader(){leader=null;}}
public class WarTypeAsset {public bool rebellion;}public class War {public WarData data=new WarData();public bool ended;public Kingdom attacker;public WarTypeAsset asset=new WarTypeAsset();public bool hasEnded(){return ended;}public WarTypeAsset getAsset(){return asset;}public bool isMainAttacker(Kingdom k){return k==attacker;}public Kingdom getMainAttacker(){return attacker;}public void lostWar(Kingdom k){ended=true;}}
public class EquipmentAsset {public string material;}public class ResourceAsset {public int maximum,storage_max;}public class ResourceLibrary {public List<ResourceAsset> list=new List<ResourceAsset>();}public class CityResources {public Dictionary<string,int> amounts=new Dictionary<string,int>();public int get(string s){int n;return amounts.TryGetValue(s,out n)?n:0;}}public class ConstructionCost{public int wood,stone,common_metals,gold;}
public static class MapSizeLibrary {public static object getPresetAsset(int n){return n>0?new object():null;}}
class RuntimeTests {
 static int checks;static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
 static City City(long id,int p){var k=new Kingdom();k.data.id=id;var c=new City();c.data.id=id;c.data.kingdomID=id;c.kingdom=k;k.capital=c;k.cities.Add(c);c.status.population=c.status.population_adults=p;World.world.cities.list.Add(c);return c;}
 static void Main(){var c=City(1,100);c.resources["wood"]=10000;c.resources["stone"]=10000;c.resources["common_metals"]=10000;
  GodWorldRuntime.Issue(c,false,1000);GodWorldRuntime.Issue(c,true,100);Check(GodWorldRuntime.GetGold(c)==1000&&GodWorldRuntime.GetGod(c)==100,"native bank balances");
  GodWorldRuntime.SetRate(2.3);double before=GodWorldRuntime.GetGold(c)+GodWorldRuntime.GetGod(c)*2.3;GodWorldRuntime.Exchange(c,false,1);Check(Math.Abs(GodWorldRuntime.GetGold(c)+GodWorldRuntime.GetGod(c)*2.3-before)<.00001,"fractional exchange conservation");
  c.takeResource("gold",40);Check(GodWorldRuntime.GetGold(c)==962,"native expense drains bank reserve");double old=GodWorldRuntime.GetGold(c);GodWorldRuntime.Issue(c,false,-1e9);Check(GodWorldRuntime.GetGold(c)==old,"over-burn rejected atomically");
  var a=new Actor{city=c};a.data.money=0;c.units.Add(a);int wage=GodWorldRuntime.PayNativeSalary(a,10);a.data.money+=wage;Check(wage==10&&GodWorldRuntime.GetGold(c)==old-10,"wage transfers city gold");int paid=GodWorldRuntime.RecordSpend(a,100);a.data.money-=paid;Check(paid==10&&a.data.money==0,"consumer never spends negative");
  int woodBefore=c.getResourcesAmount("wood");World.world.map_stats.year=1;GodWorldRuntime.TickCity(c,1);Check(c.getResourcesAmount("wood")<woodBefore,"growth consumes real native resources");int after=c.getResourcesAmount("wood");GodWorldRuntime.TickCity(c,1);Check(c.getResourcesAmount("wood")==after,"exactly one annual tick");
  int xp=NativeProgression.SkillLevel(a,0);GodWorldRuntime.Deliver(c,"wood",500,a);Check(NativeProgression.SkillLevel(a,0)>=xp,"successful work has persistent skill");
  var f=new Family();a.family=f;var heir=new Actor{family=f,city=c};f.units.Add(a);f.units.Add(heir);a.children.Add(heir);a.data.money=73;GodWorldRuntime.BeforeDeath(a);Check(a.data.money==0&&heir.data.money==73,"descendant inherits without duplication");
  var rc=new CityResources();rc.amounts["wood"]=int.MaxValue-10;Check(GodWorldRuntime.SafeResourceDelta(rc,"wood",100)==10,"resource overflow bounded");Check(GodWorldRuntime.SafeResourceDelta(rc,"wood",int.MinValue)==-(int.MaxValue-10),"resource withdrawal nonnegative");
  var rebel=City(2,6);var w=new War{attacker=rebel.kingdom};w.asset.rebellion=true;rebel.kingdom.wars.Add(w);RebellionRules.CheckDefeat(w);Check(!w.ended,"origin district six continues");rebel.status.population=5;RebellionRules.CheckDefeat(w);Check(w.ended,"origin district five fails");
  GodWorldRuntime.Flush();var retained=World.world.map_stats.custom_data;World.world.map_stats=new MapStats{year=1,custom_data=retained};Check(GodWorldRuntime.GetRate()==2.3,"rate follows saved world");Check(GodWorldRuntime.GetGod(c)>0,"god reload survives cache reset");
  var window=new CityWindow{selected=c};NativeEconomyUI.ShowCity(window);double oldA=GodWorldRuntime.GetGold(c);window.rows["发行金币"].on_click_value();Check(GodWorldRuntime.GetGold(c)==oldA+1000,"native row issues gold");var other=City(3,12);window.selected=other;NativeEconomyUI.ShowCity(window);window.rows["发行金币"].on_click_value();Check(GodWorldRuntime.GetGold(other)==1000&&GodWorldRuntime.GetGold(c)==oldA+1000,"pooled row targets current city");Check(window.rows["金币"].on_click_value==null,"read-only row clears callback");Check(NativeEconomyUI.TryClick(window.rows["发行 god"]),"owned action handles first touch");Check(!NativeEconomyUI.TryClick(window.rows["金币"]),"original read-only touch untouched");Check(GodWorldRuntime.GetGod(other)==1000,"native row issues god");var kingdomWindow=new KingdomWindow{selected=other.kingdom};NativeEconomyUI.ShowKingdom(kingdomWindow);Check(kingdomWindow.rows.ContainsKey("汇率"),"kingdom uses native rows");
  var godCity=City(4,12);godCity.resources["wood"]=100;GodWorldRuntime.Issue(godCity,true,100);var buildCost=new ConstructionCost{wood=10};double godWorth=GodWorldRuntime.GetGold(godCity)+GodWorldRuntime.GetGod(godCity)*GodWorldRuntime.GetRate();GodWorldRuntime.EnsureBuildLiquidity(godCity,buildCost);Check(GodWorldRuntime.CanFundCost(godCity,buildCost,true),"god liquidity funds native construction");Check(Math.Abs(GodWorldRuntime.GetGold(godCity)+GodWorldRuntime.GetGod(godCity)*GodWorldRuntime.GetRate()-godWorth)<1e-7,"automatic conversion preserves wealth");
  World.world.map_stats=new MapStats();Check(GodWorldRuntime.GetRate()==1,"new world has independent rate");Check(UnityEngine.Debug.warnings.Count==0,"no runtime adapter warnings");Console.WriteLine(checks+" native-adapter checks passed");
 }
}
